CREATE TABLE IF NOT EXISTS aux_import_batches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sha256 CHAR(64) NOT NULL UNIQUE,kind VARCHAR(40) NOT NULL,filename VARCHAR(500) NOT NULL,cutoff VARCHAR(40) NULL,archive_path VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_premises(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,address VARCHAR(500) NOT NULL,designation VARCHAR(200) NOT NULL,floor VARCHAR(50) NULL,kind VARCHAR(10) NOT NULL,area DECIMAL(14,3) NULL,cadastral_number VARCHAR(100) NULL,account VARCHAR(100) NULL,parent_description VARCHAR(500) NULL,parent_id BIGINT UNSIGNED NULL,note TEXT NULL,revision INT NOT NULL DEFAULT 1,creation_key VARCHAR(80) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES aux_premises(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_premise_sources(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,source_row_number INT NOT NULL,premise_id BIGINT UNSIGNED NOT NULL,identity_key VARCHAR(64) NOT NULL,hidden TINYINT NOT NULL DEFAULT 0,raw_evidence JSON NOT NULL,UNIQUE(batch_id,source_row_number,premise_id),FOREIGN KEY(batch_id) REFERENCES aux_import_batches(id),FOREIGN KEY(premise_id) REFERENCES aux_premises(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_import_identities(identity_key VARCHAR(64) PRIMARY KEY,premise_id BIGINT UNSIGNED NOT NULL,FOREIGN KEY(premise_id) REFERENCES aux_premises(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_source_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,collection VARCHAR(160) NOT NULL,source_key VARCHAR(191) NOT NULL,kind VARCHAR(30) NOT NULL,title VARCHAR(1500) NOT NULL,number VARCHAR(300) NULL,record_date VARCHAR(40) NULL,amount DECIMAL(28,8) NULL,inn VARCHAR(40) NULL,kpp VARCHAR(40) NULL,folder TINYINT NOT NULL DEFAULT 0,present TINYINT NOT NULL DEFAULT 1,deleted TINYINT NOT NULL DEFAULT 0,posted TINYINT NULL,party_id BIGINT UNSIGNED NULL,contract_id BIGINT UNSIGNED NULL,account_id BIGINT UNSIGNED NULL,revision INT NOT NULL DEFAULT 1,UNIQUE(collection,source_key),KEY(kind,folder),FOREIGN KEY(party_id) REFERENCES aux_source_records(id),FOREIGN KEY(contract_id) REFERENCES aux_source_records(id),FOREIGN KEY(account_id) REFERENCES aux_source_records(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_source_snapshots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,record_id BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,raw_evidence JSON NOT NULL,UNIQUE(batch_id,record_id),FOREIGN KEY(batch_id) REFERENCES aux_import_batches(id),FOREIGN KEY(record_id) REFERENCES aux_source_records(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_source_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,record_id BIGINT UNSIGNED NOT NULL,section VARCHAR(100) NOT NULL,position INT NOT NULL,description TEXT NULL,amount DECIMAL(28,8) NULL,vat DECIMAL(28,8) NULL,service_id BIGINT UNSIGNED NULL,contract_id BIGINT UNSIGNED NULL,invoice_id BIGINT UNSIGNED NULL,raw_evidence JSON NOT NULL,UNIQUE(record_id,section,position),FOREIGN KEY(record_id) REFERENCES aux_source_records(id),FOREIGN KEY(service_id) REFERENCES aux_source_records(id),FOREIGN KEY(contract_id) REFERENCES aux_source_records(id),FOREIGN KEY(invoice_id) REFERENCES aux_source_records(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_source_relations(record_id BIGINT UNSIGNED NOT NULL,target_id BIGINT UNSIGNED NOT NULL,field VARCHAR(150) NOT NULL,basis VARCHAR(80) NOT NULL,PRIMARY KEY(record_id,field,target_id),FOREIGN KEY(record_id) REFERENCES aux_source_records(id),FOREIGN KEY(target_id) REFERENCES aux_source_records(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS aux_issues(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identity_key CHAR(64) NOT NULL UNIQUE,record_id BIGINT UNSIGNED NULL,category VARCHAR(80) NOT NULL,title VARCHAR(1000) NOT NULL,detail TEXT NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'pending',note TEXT NULL,revision INT NOT NULL DEFAULT 1,evidence JSON NOT NULL,FOREIGN KEY(record_id) REFERENCES aux_source_records(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS market_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_key VARCHAR(80) NOT NULL UNIQUE,created_at DATETIME(6) NOT NULL,snapshot_hash CHAR(64) NOT NULL,settings_hash CHAR(64) NOT NULL,archive_path VARCHAR(500) NOT NULL,records_count INT NOT NULL,imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS market_observations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_id BIGINT UNSIGNED NOT NULL,position INT NOT NULL,source VARCHAR(20) NOT NULL,object_type VARCHAR(20) NOT NULL,scope VARCHAR(20) NOT NULL,source_id VARCHAR(191) NULL,source_url TEXT NULL,address VARCHAR(500) NOT NULL,area DECIMAL(20,4) NULL,price_rub DECIMAL(28,4) NULL,price_period VARCHAR(20) NULL,annual_rate_rub_m2 DECIMAL(28,4) NULL,currency VARCHAR(10) NULL,identity_key VARCHAR(500) NULL,raw_evidence JSON NOT NULL,UNIQUE(run_id,position),KEY(run_id,source,object_type,scope),FOREIGN KEY(run_id) REFERENCES market_runs(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS market_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_id BIGINT UNSIGNED NOT NULL,source VARCHAR(20) NULL,object_type VARCHAR(20) NULL,scope VARCHAR(20) NULL,outcome VARCHAR(40) NULL,partial TINYINT NOT NULL DEFAULT 0,raw_evidence JSON NOT NULL,FOREIGN KEY(run_id) REFERENCES market_runs(id)) ENGINE=InnoDB;
